import { defineConfig } from 'vite'
import type { Plugin } from 'vite'
import react from '@vitejs/plugin-react'
import fs from 'node:fs'
import path from 'node:path'

// public/live/ is generated by `npm run fetch:clouds` (and by the deploy
// workflow) and is not committed. When it has not been generated, serve and
// emit a placeholder manifest so the app falls back to the static cloud map
// without a 404 in the console.
const LIVE_MANIFEST = 'live/manifest.json'
const PLACEHOLDER   = JSON.stringify({ version: 1, generatedAt: null, clouds: null }) + '\n'

function liveManifestFallback(): Plugin {
  let realManifest = path.resolve('public', LIVE_MANIFEST)
  return {
    name: 'live-manifest-fallback',
    configResolved(config) {
      if (config.publicDir) realManifest = path.join(config.publicDir, LIVE_MANIFEST)
    },
    configureServer(server) {
      const url = server.config.base + LIVE_MANIFEST
      server.middlewares.use((req, res, next) => {
        if (req.url?.split('?')[0] !== url || fs.existsSync(realManifest)) return next()
        res.setHeader('Content-Type', 'application/json')
        res.setHeader('Cache-Control', 'no-cache')
        res.end(PLACEHOLDER)
      })
    },
    generateBundle() {
      if (!fs.existsSync(realManifest)) {
        this.emitFile({ type: 'asset', fileName: LIVE_MANIFEST, source: PLACEHOLDER })
      }
    },
  }
}

export default defineConfig({
  plugins: [react(), liveManifestFallback()],
  base: '/aboo-portfolio/',
})
